/// <summary>
/// Delegate for adding additional initialization logic for the label.
/// </summary>
/// <param name = "_label">License plate label being created.</param>
/// <param name = "_workLine">Work line used to initialize the label.</param>
/// <param name = "_converter">Unit of measure converter.</param>
/// <param name = "_labelBuilder">License plate label builder class instance.</param>
[
    SubscribesTo(classStr(WHSLicensePlateLabelBuild), delegateStr(WHSLicensePlateLabelBuild, labelInitialized))
]
public static void WHSLicensePlateLabelBuild_labelInitialized(WHSLicensePlateLabel _label, WHSWorkLine _workLine, EcoResReleasedProductUnitConverter _converter, WHSLicensePlateLabelBuild _labelBuilder)
{
    _labelBuilder.avaInitializeLabelFromWorkLines(_workLine, _converter);

}
